from typing import List

from .message_handling import (Structure, SMessageHeader, SBrowserObject, SMessageAddress,
                               RequestMessage, ResponseMessage, Query, BasicQueryManager,
                               register_message, u32)
from ..utils import get_context_id, get_procedure_id

from .sack_reflection_interface import EReportingMode, EBrowserObjectName, get_user_name

MAX_NUM_OF_ITEMS_IN_USER_LIST_ACK_MSG = 140


@register_message
class BrowserUserListReq(RequestMessage):
    id = 0x1b4a

    _fields_ = [
        ('header', SMessageHeader),
        ('reportingMode', u32),
        ('contextId', u32),
        ('procedureId', u32),
        ('subsystem', SBrowserObject),
        ('browserObject', SBrowserObject),
    ]

    def __init__(self, board, cpu, *args, **kwargs):
        super(BrowserUserListReq, self).__init__(board, cpu, *args, **kwargs)
        self.reportingMode = EReportingMode.EReportingMode_Single
        self.contextId = get_context_id()
        self.procedureId = get_procedure_id()
        self.subsystem.objectName = EBrowserObjectName.EBrowserObjectName_Cpu
        self.subsystem.objectId = cpu
        self.browserObject.objectName = EBrowserObjectName.EBrowserObjectName_Cpu
        self.browserObject.objectId = 0


class SBrowserUser(Structure):
    _fields_ = [
        ('userId', u32),
        ('userType', u32),
        ('userState', u32),
        ('userAddr', SMessageAddress)
    ]

    def __str__(self):
        return '{} ({})'.format(self.userId, get_user_name(self.userType))


@register_message
class BrowserUserListAck(ResponseMessage):
    id = 0x1b4b

    _fields_ = [
        ('header', SMessageHeader),
        ('status', u32),
        ('contextId', u32),
        ('procedureId', u32),
        ('userCountTotal', u32),
        ('userCountInThisMessage', u32),
        ('userList', SBrowserUser * MAX_NUM_OF_ITEMS_IN_USER_LIST_ACK_MSG)
    ]


@register_message
class BrowserHsupaUserListReq(RequestMessage):
    id = 0x1e28

    _fields_ = [
        ('header', SMessageHeader),
        ('reportingMode', u32),
        ('contextId', u32),
        ('procedureId', u32),
        ('subsystem', SBrowserObject),
        ('browserObject', SBrowserObject),
    ]

    def __init__(self, board, cpu, *args, **kwargs):
        super(BrowserHsupaUserListReq, self).__init__(board, cpu, *args, **kwargs)
        self.reportingMode = EReportingMode.EReportingMode_Single
        self.contextId = get_context_id()
        self.procedureId = get_procedure_id()
        self.subsystem.objectName = EBrowserObjectName.EBrowserObjectName_Cpu
        self.subsystem.objectId = cpu
        self.browserObject.objectName = EBrowserObjectName.EBrowserObjectName_Cpu
        self.browserObject.objectId = 0


@register_message
class BrowserHsupaUserListAck(ResponseMessage):
    id = 0x1e10

    _fields_ = [
        ('header', SMessageHeader),
        ('status', u32),
        ('contextId', u32),
        ('procedureId', u32),
        ('userCountTotal', u32),
        ('userCountInThisMessage', u32),
        ('userList', SBrowserUser * MAX_NUM_OF_ITEMS_IN_USER_LIST_ACK_MSG)
    ]


class BrowserUserListQuery(Query):
    def __init__(self, req, resp):
        super(BrowserUserListQuery, self).__init__(req, resp)

        self._actual_count = 0
        self._expected_total_count = 0
        self.user_list = []

    def _handle_response(self):
        self._expected_total_count = self.resp_msg.userCountTotal
        count_in_this_message = self.resp_msg.userCountInThisMessage
        self._actual_count += count_in_this_message
        for user in self.resp_msg.userList[:count_in_this_message]:
            self.user_list.append(user.get_copy())

    def _decide_if_complete(self):
        if self._actual_count == self._expected_total_count:
            self.complete = True


BrowserHsupaUserListQuery = BrowserUserListQuery


class UserListInterface(object):
    def __init__(self, connection):
        self.connection = connection

    def get_users(self, board, cpu):
        # type: (int, int) -> List[SBrowserUser]
        query = BrowserUserListQuery(BrowserUserListReq(board, cpu), BrowserUserListAck())
        qm = BasicQueryManager(query, self.connection)
        qm.send_request_and_wait_for_response()

        return query.user_list

    def get_user_ids(self, board, cpu):
        # type: (int, int) -> List[int]
        users = self.get_users(board, cpu)
        return sorted([user.userId for user in users])

    def get_hsupa_users(self, board, cpu):
        # type: (int, int) -> List[SBrowserUser]
        query = BrowserHsupaUserListQuery(BrowserHsupaUserListReq(board, cpu), BrowserHsupaUserListAck())
        qm = BasicQueryManager(query, self.connection)
        qm.send_request_and_wait_for_response()

        return query.user_list

    def get_hsupa_user_ids(self, board, cpu):
        # type: (int, int) -> List[int]
        hsupa_users = self.get_hsupa_users(board, cpu)
        return sorted([user.userId for user in hsupa_users])

    def filter_out_single_user_with_type(self, user_type, user_list):
        # type: (int, List[SBrowserUser]) -> SBrowserUser
        for user in user_list:
            if user.userType == user_type:
                return user
